# Tarea
Escribe la vista MIP del modelo del problema **Job shop scheduling (makespan)**, como DATOS (sin llamar a ningún solver). La vista heurística ya está escrita y aprobada contra los casos de prueba: NO la cambies ni la redefinas; tu módulo se concatena DESPUÉS de ella, así que puedes usar sus funciones (canonical, cost_terms…) directamente; no la importes (no es un módulo aparte).

# El problema
Hay `inst.n_jobs` trabajos y `inst.n_machines` máquinas. Cada trabajo j tiene una ruta `inst.routes[j]`: una secuencia de operaciones (máquina, tiempo de proceso) que se deben hacer en ese orden, cada una en su máquina, sin interrupción; la operación k+1 de un trabajo no puede empezar antes de que termine la k. Cada máquina procesa una operación a la vez. Cada trabajo pasa a lo sumo una vez por cada máquina. Una solución fija el orden de las operaciones en cada máquina, y el plan es el SEMIACTIVO: cada operación empieza apenas terminan la anterior de su trabajo y la anterior de su máquina. Objetivo: minimizar el makespan (el instante en que termina la última operación). Si los órdenes de las máquinas forman un ciclo con las rutas (A antes que B en una máquina y B antes que A, directa o indirectamente, en otra) no hay plan: la solución es infactible. Una solución infactible debe tener un objetivo finito pero peor que cualquier factible (penalización).

# La instancia
```python
@dataclass(frozen=True)
class JSSPInstance:
    # routes[j] = ruta del trabajo j: tupla de operaciones (máquina, tiempo de proceso) en el orden obligatorio
    routes: tuple[tuple[tuple[int, int], ...], ...]
    n_machines: int

    @property
    def n_jobs(self) -> int:
        return len(self.routes)

    @property
    def jobs(self) -> range:
        return range(len(self.routes))

    @property
    def machines(self) -> range:
        return range(self.n_machines)

    def machine(self, j: int, k: int) -> int:
        return self.routes[j][k][0]

    def proc(self, j: int, k: int) -> int:
        return self.routes[j][k][1]

    def op_index(self, j: int, m: int) -> int | None:
        """Posición en la ruta del trabajo j de su operación en la máquina m (None si no pasa por m)."""
        for k, (mm, _) in enumerate(self.routes[j]):
            if mm == m:
                return k
        return None

    def horizon(self) -> int:
        """Suma de todos los tiempos de proceso: cota superior de cualquier inicio de un plan semiactivo."""
        return sum(p for r in self.routes for _, p in r)

    @staticmethod
    def random(n_jobs: int, n_machines: int, rng: Random) -> "JSSPInstance":
        """Como las de Taillard (1993): cada trabajo pasa una vez por cada máquina, en un orden al azar,
        con tiempos de proceso enteros uniformes en 1..99."""
        routes = []
        for _ in range(n_jobs):
            order = list(range(n_machines))
            rng.shuffle(order)
            routes.append(tuple((m, rng.randint(1, 99)) for m in order))
        return JSSPInstance(tuple(routes), n_machines)

    def to_text(self) -> str:
        """Formato de entrada (el de la OR-Library): `n m`, luego una línea por trabajo con los pares
        `máquina tiempo` de sus operaciones en orden (máquinas numeradas desde 0)."""
        lines = [f"{self.n_jobs} {self.n_machines}"]
        lines += [" ".join(f"{m} {p}" for m, p in r) for r in self.routes]
        return "\n".join(lines) + "\n"

    @staticmethod
    def parse(text: str) -> "JSSPInstance":
        lines = [ln for ln in text.splitlines() if ln.strip()]
        n, m = map(int, lines[0].split())
        routes = []
        for ln in lines[1:n + 1]:
            vals = list(map(int, ln.split()))
            routes.append(tuple((vals[i], vals[i + 1]) for i in range(0, len(vals), 2)))
        assert len(routes) == n, "se esperaban n líneas de trabajos"
        return JSSPInstance(tuple(routes), m)

    def save(self, path: str) -> None:
        with open(path, "w") as f:
            f.write(self.to_text())

    @staticmethod
    def load(path: str) -> "JSSPInstance":
        with open(path) as f:
            return JSSPInstance.parse(f.read())

```

# Vista heurística aprobada (ya definida antes de tu código)
```python
from functools import lru_cache
from collections import deque
from examples.jobshop.instance import JSSPInstance


def canonical(sol):
    return tuple(tuple(int(x) for x in seq) for seq in sol)


def trivial_solution(inst):
    # Same global job order on every machine: never creates a cycle.
    seqs = []
    for m in inst.machines:
        seqs.append(tuple(j for j in inst.jobs if inst.op_index(j, m) is not None))
    return canonical(seqs)


def random_solution(inst, rng):
    # Random dispatch: always acyclic (feasible), with a random structure.
    nxt = [0] * inst.n_jobs
    seqs = [[] for _ in inst.machines]
    pending = [j for j in inst.jobs if len(inst.routes[j]) > 0]
    while pending:
        i = rng.randrange(len(pending))
        j = pending[i]
        m = inst.machine(j, nxt[j])
        seqs[m].append(j)
        nxt[j] += 1
        if nxt[j] >= len(inst.routes[j]):
            pending[i] = pending[-1]
            pending.pop()
    return canonical(seqs)


def from_answer(inst, answer):
    return canonical(answer)


@lru_cache(maxsize=4096)
def _evaluate(inst, sol):
    n, M = inst.n_jobs, inst.n_machines
    # --- secuencia ---
    sec = 0
    cleaned = []
    for m in range(M):
        expected = {j for j in range(n) if inst.op_index(j, m) is not None}
        seq = sol[m] if m < len(sol) else ()
        seen = set()
        clean = []
        for j in seq:
            if j in expected and j not in seen:
                seen.add(j)
                clean.append(j)
            else:
                sec += 1  # sobra o se repite
        sec += len(expected - seen)  # faltan
        cleaned.append(clean)
    for m in range(M, len(sol)):
        sec += len(sol[m])

    # --- orden: grafo de operaciones ---
    offs = [0] * (n + 1)
    for j in range(n):
        offs[j + 1] = offs[j] + len(inst.routes[j])
    N = offs[n]
    succ = [[] for _ in range(N)]
    indeg = [0] * N
    dur = [0] * N
    for j in range(n):
        for k in range(len(inst.routes[j])):
            u = offs[j] + k
            dur[u] = inst.proc(j, k)
            if k + 1 < len(inst.routes[j]):
                succ[u].append(u + 1)
                indeg[u + 1] += 1
    for m in range(M):
        clean = cleaned[m]
        for a, b in zip(clean, clean[1:]):
            u = offs[a] + inst.op_index(a, m)
            v = offs[b] + inst.op_index(b, m)
            succ[u].append(v)
            indeg[v] += 1
    start = [0] * N
    q = deque(u for u in range(N) if indeg[u] == 0)
    done = 0
    mk = 0
    while q:
        u = q.popleft()
        done += 1
        f = start[u] + dur[u]
        if f > mk:
            mk = f
        for v in succ[u]:
            if f > start[v]:
                start[v] = f
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    orden = N - done
    H = inst.horizon()
    if sec > 0 or orden > 0:
        cost = float(H + 1 + H * (sec + orden))
    else:
        cost = float(mk)
    return float(sec), float(orden), cost


def violations(inst, sol):
    sec, orden, _ = _evaluate(inst, canonical(sol))
    return {"secuencia": sec, "orden": orden}


def cost_terms(inst, sol):
    _, _, cost = _evaluate(inst, canonical(sol))
    return {"makespan": cost}

```

# Representación de la solución (obligatoria)
Una tupla con una secuencia por máquina (en el orden de las máquinas 0..m-1): la tupla de trabajos en el orden en que esa máquina los procesa. Es la que usan los vecindarios clásicos del job shop (intercambios en los bloques del camino crítico).

# Funciones a escribir: la vista MIP como DATOS (el framework arma el modelo del solver y lo resuelve)

def variables(inst) -> dict[str, tuple[float, float, str]]: ...   # {nombre: (cota_inf, cota_sup, "binary" | "continuous")}
def structural_variables(inst) -> list[str]: ...    # las binarias que describen la solución (las demás son auxiliares)
def to_assignment(inst, sol) -> dict[str, float]: ...   # valor de TODAS las estructurales para `sol`
def aux_values(inst, sol) -> dict[str, float]: ...      # valor de TODAS las auxiliares en el punto de `sol` (p.ej. cargas, inventarios)
def from_assignment(inst, x) -> "sol": ...          # inversa: from_assignment(inst, to_assignment(inst, sol)) == sol (factibles)
def constraint_families(inst) -> dict[str, list[tuple[dict[str, float], str, float]]]: ...
    # {familia: [(coeficientes {variable: coef}, sentido "<=" | ">=" | "==", lado derecho), ...]}
    # El nombre de la familia (o su prefijo antes de un punto, p.ej. "visita.entrada") debe ser el nombre que
    # usa `violations`: se verificará que la familia del MIP se viola exactamente cuando violations la reporta.
def objective_terms(inst) -> dict[str, tuple[dict[str, float], float]]: ...
    # {término: (coeficientes, constante)} con los MISMOS nombres de término que cost_terms
def variable_groups(inst) -> dict[str, list[str]]: ...   # partición de structural_variables en bloques CHICOS
    # (al menos 4, ninguno con más de un tercio), según la estructura del problema: Fix-and-Optimize
    # libera de a 1 a 4 grupos por subproblema, y Relax-and-Fix fija un grupo por vez. Agrupa variables que
    # interactúan (elementos cercanos, el mismo período…): con todo lo demás fijo, liberar un grupo tiene que
    # dejar espacio para cambiar la solución


